<?php
declare(strict_types=1);
// Execute via cron CLI, por exemplo: php /home/USUARIO/public_html/cron/reminders.php
if(PHP_SAPI!=='cli'){http_response_code(403);exit('CLI only');}
require dirname(__DIR__).'/app/bootstrap.php';if(!is_installed())exit("not installed\n");$now=date('Y-m-d H:i:s');$windows=[['hours'=>24,'field'=>'reminder_24h_at','template'=>'appointment_24h'],['hours'=>2,'field'=>'reminder_2h_at','template'=>'appointment_2h']];foreach($windows as $w){$from=(new DateTimeImmutable())->modify('+'.$w['hours'].' hours -10 minutes')->format('Y-m-d H:i:s');$to=(new DateTimeImmutable())->modify('+'.$w['hours'].' hours +10 minutes')->format('Y-m-d H:i:s');$field=$w['field'];$st=db()->prepare("SELECT a.id,a.tenant_id,a.starts_at,a.public_token,p.phone,p.preferred_name,p.name,u.name professional_name FROM appointments a JOIN patients p ON p.id=a.patient_id AND p.tenant_id=a.tenant_id JOIN users u ON u.id=a.professional_id AND u.tenant_id=a.tenant_id WHERE a.status IN ('pending','confirmed') AND a.starts_at BETWEEN :f AND :to AND a.{$field} IS NULL AND p.phone IS NOT NULL AND p.phone<>''");$st->execute(['f'=>$from,'to'=>$to]);foreach($st->fetchAll() as $a){$payload=['patient_name'=>$a['preferred_name']?:$a['name'],'professional_name'=>$a['professional_name'],'starts_at'=>$a['starts_at'],'confirm_url'=>url('confirm.php?token='.$a['public_token'])];db()->prepare("INSERT INTO notification_queue(tenant_id,appointment_id,channel,destination,template,payload_json,scheduled_at,status,created_at)VALUES(:t,:a,'whatsapp',:d,:tpl,:p,NOW(),'queued',NOW())")->execute(['t'=>$a['tenant_id'],'a'=>$a['id'],'d'=>$a['phone'],'tpl'=>$w['template'],'p'=>json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);db()->prepare("UPDATE appointments SET {$field}=NOW() WHERE id=:id AND tenant_id=:t")->execute(['id'=>$a['id'],'t'=>$a['tenant_id']]);}}
// Entrega por webhook configurável. Sem URL, a fila permanece queued para integração posterior.
$url=trim((string)env('WHATSAPP_WEBHOOK_URL',''));if($url!==''){$st=db()->query("SELECT * FROM notification_queue WHERE status='queued' AND scheduled_at<=NOW() ORDER BY id LIMIT 50");foreach($st->fetchAll() as $n){$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: Bearer '.env('WHATSAPP_WEBHOOK_TOKEN','')],CURLOPT_POSTFIELDS=>json_encode(['to'=>$n['destination'],'template'=>$n['template'],'data'=>json_decode($n['payload_json']?:'{}',true)],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),CURLOPT_TIMEOUT=>20]);$resp=curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);$err=curl_error($ch);curl_close($ch);if($resp!==false&&$code>=200&&$code<300)db()->prepare("UPDATE notification_queue SET status='sent',sent_at=NOW() WHERE id=:id")->execute(['id'=>$n['id']]);else db()->prepare("UPDATE notification_queue SET status='failed',error_message=:e WHERE id=:id")->execute(['e'=>substr($err?:'HTTP '.$code,0,500),'id'=>$n['id']]);}}
echo "reminders processed {$now}\n";
